using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.LowLevel;
public class Script{
 static PlayerLoopSystem previousLoop;static float previousCapture;static List<ParticleSystem> systems;static List<object> rows;static bool spawned,finished;static int frame;static string output;sealed class ShapeContinuousHook{}
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");output="OUTPUT_FILE";var clean=PlayerLoop.GetCurrentPlayerLoop();for(int i=0;i<clean.subSystemList.Length;i++){var phase=clean.subSystemList[i];if(phase.subSystemList==null)continue;var list=new List<PlayerLoopSystem>(phase.subSystemList);list.RemoveAll(x=>x.type!=null&&x.type.Name=="ShapeContinuousHook");phase.subSystemList=list.ToArray();clean.subSystemList[i]=phase;}PlayerLoop.SetPlayerLoop(clean);previousLoop=PlayerLoop.GetCurrentPlayerLoop();previousCapture=Time.captureDeltaTime;Time.captureDeltaTime=1f/60;systems=new List<ParticleSystem>();rows=new List<object>();var loop=PlayerLoop.GetCurrentPlayerLoop();for(int i=0;i<loop.subSystemList.Length;i++)if(loop.subSystemList[i].type==typeof(UnityEngine.PlayerLoop.PostLateUpdate)){var p=loop.subSystemList[i];var list=new List<PlayerLoopSystem>(p.subSystemList);list.Add(new PlayerLoopSystem{type=typeof(ShapeContinuousHook),updateDelegate=Tick});p.subSystemList=list.ToArray();loop.subSystemList[i]=p;break;}File.WriteAllText(output,"{\"pending\":true}");PlayerLoop.SetPlayerLoop(loop);return "Automatic seed/age birth order started";}
 static void Tick(){if(finished)return;try{
 if(!spawned){foreach(var shapeType in new[]{ParticleSystemShapeType.Circle,ParticleSystemShapeType.Cone})foreach(float rate in new[]{60f,100f,120f,200f,1000f,2000f})foreach(int capacity in new[]{16,128}){
 var go=new GameObject("birth-order-probe"){hideFlags=HideFlags.HideAndDontSave};var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.playOnAwake=false;m.startLifetime=2;m.startSpeed=0;m.startSize=1;m.maxParticles=capacity;m.startRotation=0;m.cullingMode=ParticleSystemCullingMode.AlwaysSimulate;var e=ps.emission;e.enabled=true;e.rateOverTime=rate;var sh=ps.shape;sh.enabled=true;sh.shapeType=shapeType;sh.radius=.75f;sh.radiusThickness=.2f;sh.arc=120;sh.arcMode=ParticleSystemShapeMultiModeValue.Random;sh.angle=25;ps.useAutoRandomSeed=false;ps.randomSeed=12345;ps.Play();systems.Add(ps);
 }spawned=true;return;}
 frame++;foreach(var ps in systems){var particles=new ParticleSystem.Particle[128];var count=ps.GetParticles(particles);var values=new List<object>();for(int i=0;i<count;i++){var p=particles[i];values.Add(new{seed=p.randomSeed,position=new[]{p.position.x,p.position.y,p.position.z}});}rows.Add(new{frame,shape=(int)ps.shape.shapeType,rate=ps.emission.rateOverTime.constant,capacity=ps.main.maxParticles,time=ps.time,dt=Time.deltaTime,particles=values});}
 if(frame<12)return;File.WriteAllText(output,System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,unityVersion=Application.unityVersion,driver="automatic continuous rate, PostLateUpdate, no Emit or Simulate",systemSeed=12345,rows}));Cleanup();
 }catch(Exception e){File.WriteAllText(output,System.Text.Json.JsonSerializer.Serialize(new{error=e.ToString()}));Cleanup();}}
 static void Cleanup(){finished=true;PlayerLoop.SetPlayerLoop(previousLoop);Time.captureDeltaTime=previousCapture;foreach(var ps in systems)if(ps!=null)UnityEngine.Object.DestroyImmediate(ps.gameObject);}
}
